        description: '《笠翁对韵》四支其四中段。原文：「专诸剑，博浪椎。经纬对干支。位尊民物主，德重帝王师。」专诸念 zhuān zhū，春秋吴国堂邑勇士，伍子胥把他荐给公子光；吴王僚爱吃炙鱼，专诸专门学烤鱼，把匕首藏在鱼腹里，宴上献鱼时抽刀刺僚，僚当场毙命，专诸也被杀，那把匕首后来叫鱼肠剑，公子光即位为吴王阖闾，司马迁把这桩事写进《刺客列传》且列在首位。博浪椎是张良的家国之恨：他是韩国相门之后，秦灭韩，弟弟死了不办丧事，散尽家财求刺客，找到大力士铸一百二十斤铁椎，秦始皇东巡过博浪沙（今河南原阳）时椎击车队，误中副车，张良改名换姓逃到下邳，后来得黄石公兵书，成汉初三杰；椎念 zhuī，是砸物的铁锤。经纬对干支：经纬是布上的竖线与横线，一纵一横织成整匹，引申为地上的方位条理；干支是天干十、地支十二，一干配一支排成六十甲子，用来纪年纪日；一经一纬讲空间，一干一支讲时间，都成套有序。位尊民物主说地位最尊的人是百姓与万物的主人，指天子，位越高担子越重；德重帝王师说德行最厚的人可以做帝王的老师，古人讲「帝者与师处」。全课由两桩旧事起，中间一副名目，末联归到人与德：位子管人，德行管心。韵脚椎、支、师，同押四支；剑为仄声收句不入韵。',
