        grade: '小学低中年级',
        description: '《笠翁对韵》四支其四末段，四支全韵到此讲完。原文：「望切不妨人去远，心忙无奈马行迟。金屋闭来，赋乞茂陵题柱笔；玉楼成后，记须昌谷负囊词。」前两句写「急也没用」：望切是盼望得急切，不妨是不碍、挡不住，眼睛追不上脚步，人要走拦不住；心忙是心里发慌，无奈是没辙，马行迟是马走得慢，心再快也催不动一匹慢马。后两句用两个与文章有关的旧事。金屋闭来用汉武帝幼时「若得阿娇作妇，当作金屋贮之」的旧话，阿娇做了陈皇后，失宠被废、退居长门宫，拿出黄金百斤请司马相如作《长门赋》，想打动武帝；茂陵是司马相如晚年所居（今陕西兴平），古人以居地称人，通行本作「茂陵」，有的本子写「茂林」是形近抄误；题柱是他初入长安过升仙桥，在桥柱上写「不乘赤车驷马，不过汝下」，是立志之笔。玉楼成后用李贺的故事：传说他临终见绯衣人传玉帝旨，说白玉楼已成、请他去作记，不久便死，年仅二十七；昌谷是李贺籍贯（今河南宜阳），故称李昌谷；负囊是他骑驴出门、让小童背锦囊跟着，想出好句写下投入囊中，回家倒出来整理成诗，他母亲心疼说「是儿要呕出心乃已」。对法上前两句是心情对心情，后两句是典对典：金屋对玉楼、闭来对成后、赋乞对记须、茂陵题柱笔对昌谷负囊词，一悲一奇，一个求人一个被求。韵脚迟、词，同押四支；远、笔为仄声收句不入韵。',
