        description: '《笠翁对韵》五微其一开篇，五微是新的一韵。原文：「贤对圣，是对非。觉奥对参微。鱼书对雁字，草舍对柴扉。」贤念 xián，才德出众，比众人高出一截，还没到顶；圣念 shèng，德与智都到了顶，古人说「人伦之至谓之圣」，贤次圣一等，一低一高正成对。是对非，一正一反，分的是对错：贤圣比高低，是非分对错，两副心思。觉奥对参微：觉念 jué 是明白、醒悟，不是 jiào；奥本指屋子西南角那个最深最暗处，引申为深奥，觉奥就是领悟那层深意；参念 cān 是参究体察，微是细微处，参微就是连最细的理也不放过；一深一细，都是往深里钻的功夫。鱼书对雁字，都是书信：鱼书出古乐府「客从远方来，遗我双鲤鱼，呼儿烹鲤鱼，中有尺素书」，后人便以鱼书、鱼素称信；雁字是大雁飞时排成「一」字或「人」字，苏武被困匈奴，汉使称天子射得雁、足上系帛书，匈奴才放人，故有雁足传书之说；一在水一在天，同一意思两种说法。草舍对柴扉：草舍是茅草盖的屋，舍念 shè 不念 shě；柴扉是柴条编的门，扉念 fēi 是门扇；一屋一门，整体对部件，都写清贫人家。全课要点是先分门类再求工整：人配人、理配理、信配信、屋配门。韵脚非、微、扉，同押五微。',
