        subtitle: '《笠翁对韵》五微其二第二段：占鸿渐',
        path: 'lessons/628-zhan-hong-jian/index.html',
        grade: '小学低中年级',
        description: '《笠翁对韵》五微其二第二段。原文：「占鸿渐，采凤飞。虎榜对龙旗。心中罗锦绣，口内吐珠玑。」占念 zhān，是占卜看兆头，不念 zhàn；鸿渐出《周易·渐卦》，卦辞写鸿雁从水边飞到岸上，再上高地、上树、上山陵，一级一级往高处落脚，所以「鸿渐」比喻人做官做事逐步升进，急不得，占鸿渐就是卜得这么一支好卦。采是取、采纳；凤飞出《诗经·大雅·卷阿》「凤凰于飞，翙翙其羽」，凤凰一飞就是祥瑞，也比喻贤才遇上好时候；占是卜、采是取，两个动词都在求好兆。虎榜是科举时代的进士榜，唐贞元八年陆贽主考，取中韩愈等二十三人，当时人称「龙虎榜」，后来虎榜就成了进士榜的代称，读书人一生就盼这一张纸；龙旗是画着龙的天子旗帜、军中大旗，《诗经·周颂》「龙旗阳阳」写的就是祭礼上龙旗飘动的样子；虎对龙是一兽一神物，榜对旗是一纸一布，一个贴在墙上，一个飘在天上。心中罗锦绣：罗是罗列铺开，锦绣是织了花纹的丝织品，最贵重的东西，心里铺着锦绣是说肚子里有货有文章，成语「胸罗锦绣」；口内吐珠玑：珠玑都是珍珠，圆的叫珠、不圆的叫玑，一开口字字像珠子落下来，成语「口吐珠玑」与「锦心绣口」是一路。这两句一藏一吐，写成才与口才，次序是先有里子再有面子。韵脚飞、旗、玑，同押五微；渐为仄声收句不入韵。',
