        title: '五微 · 宽宏豁达高皇量（其二末段·五微其二终）',
        subtitle: '《笠翁对韵》五微其二末段：宽宏豁达高皇量',
        path: 'lessons/629-kuan-hong-huo-da/index.html',
        grade: '小学低中年级',
        description: '《笠翁对韵》五微其二末段，五微其二三段到此讲完。原文：「宽宏豁达高皇量，叱咤喑哑霸主威。灭项兴刘，狡兔尽时走狗死；连吴拒魏，貔貅屯处卧龙归。」上半段说两个人。宽宏豁达是心胸宽、看得开，高皇是汉高祖刘邦，量念 liàng 是气量；刘邦的本事不在能打在能容，韩信、陈平都是从项羽那边跑来的，他敢用，进咸阳不杀子婴只约法三章，雍齿反过他他还先封雍齿安人心。叱咤念 chì zhà 是怒喝，喑哑这里念 yīn yǎ，是厉声怒叫、不是嗓子哑，出《史记·淮阴侯列传》韩信评项羽「项王喑哑叱咤，千人皆废」；霸主即西楚霸王项羽，威是威势不是威望。下半段说两桩事。灭项兴刘，出力最大的是韩信：明修栈道暗度陈仓、背水一战、十面埋伏，最后垓下围住项羽；刘邦自己承认「连百万之军，战必胜，攻必取，吾不如韩信」。狡兔尽时走狗死出《史记》「狡兔死，良狗烹；高鸟尽，良弓藏；敌国破，谋臣亡」，走狗就是猎狗，兔子打完猎狗下锅，比喻功臣失势被除；韩信先封楚王，后贬淮阴侯，最后被吕后骗进长乐宫杀掉。连吴拒魏是诸葛亮在隆中就定的策：曹操不可硬争，孙权可以为援，后来成了赤壁之战。貔貅念 pí xiū，传说中的猛兽，古书里比勇猛的军队；屯处是驻扎的地方；卧龙是诸葛亮隐居南阳时的称号，归是归附归心。对法上宽宏豁达对叱咤喑哑是四字对四字、一宽一猛；高皇对霸主、量对威；灭项兴刘对连吴拒魏一灭一兴一连一拒；狡兔对貔貅、走狗对卧龙、尽时对屯处、死对归。韵脚威、归，同押五微。',
