        subtitle: '《笠翁对韵》五微其三第二段：乌衣巷，燕子矶',
        path: 'lessons/631-wu-yi-xiang/index.html',
        grade: '小学低中年级',
        description: '《笠翁对韵》五微其三第二段。原文：「乌衣巷，燕子矶。久别对初归。天姿真窈窕，圣德实光辉。」三对分三层。第一对是两个南京地名：乌衣巷在秦淮河边，东晋王导、谢安两大家族住这里，子弟都穿乌衣（黑衣）故名，刘禹锡写「朱雀桥边野草花，乌衣巷口夕阳斜，旧时王谢堂前燕，飞入寻常百姓家」；燕子矶在城北长江边，一块三面临水的悬崖，形如燕子展翅，矶念 jī 是水边突出的岩石，长江三大矶（燕子矶、采石矶、城陵矶）里它居首，人称万里长江第一矶。第二对讲聚散：久是时间长、别是分开，初不是第一次而是「刚刚」，归是回到自己地方；久对初是时间长短，别对归是出门对回家，方向相反。第三对讲貌与德：天姿是天生的姿容，真是确实；窈窕念 yǎo tiǎo，形容女子体态美好神态安静，出《诗经·周南·关雎》「窈窕淑女，君子好逑」，是联绵词，两个字拆不开不能分训；圣德是圣贤的德行，实是实在，光辉是光明照耀——德行不是自己夸，是照到别人身上才叫光辉。对法上地名对地名（乌、燕都是鸟，巷、矶都是地方）、时间对时间、貌对德（一外一内）。落点：巷子会旧、德行不朽，容貌照一时、德行照一世。韵脚矶、归、辉，同押五微。',
