        description: '《笠翁对韵》五微其三末段，五微全篇收官。原文：「蟠桃紫阙来金母，岭荔红尘进玉妃。霸主军营，亚父丹心撞玉斗；长安酒市，谪仙狂兴换银龟。」四句四个典故。上半写两样进献：蟠桃是仙桃，传说三千年一开花三千年一结果，紫阙是天宫，金母即西王母（西方属金），蟠桃会是她做东；岭荔是岭南荔枝，玉妃是杨贵妃，杜牧「一骑红尘妃子笑，无人知是荔枝来」写的就是驿马扬尘送鲜荔。下半写两股意气：霸主是西楚霸王项羽，鸿门宴上亚父范增（项羽尊他如父、仅次于父）几次举玉玦示意杀刘邦，项羽不忍，刘邦借机逃走，张良代献玉斗，范增拔剑撞碎，骂「竖子不足与谋」；谪仙是李白，贺知章初见惊呼「谪仙人」，狂兴是狂放的兴致，银龟是唐代五品以上官员佩的龟符，传说李白兴起解龟符换酒。对法上蟠桃紫阙对岭荔红尘（天上对人间）、来金母对进玉妃（金玉相称、母妃相称）、霸主军营对长安酒市（军营对酒市、一武一文）、亚父丹心撞玉斗对谪仙狂兴换银龟。落点：前两句说进献，后两句说意气——捧上来的身外物再贵也会散，心里那口气才留得住。韵脚妃、龟，同押五微。',
