        description: '《笠翁对韵》六鱼其一第二段。原文：「周有若，汉相如。玉屋对匡庐。月明山寺远，风细水亭虚。」这一段从名物转到人和景，分三层。第一层记人：有若是春秋时孔子弟子，字子有，《论语》称「有子」，长得像孔子，因是周朝人故称周有若；相如是西汉辞赋家司马相如，四川成都人，代表作《子虚赋》《上林赋》，汉武帝读后大加赞赏，因是汉朝人故称汉相如——朝代对朝代、人名对人名。第二层记山：玉屋通行本多作「王屋」，指王屋山，在山西阳城、垣曲之间，山有三重、其状如屋故名，寓言「愚公移山」移的就是它；匡庐就是庐山，在江西九江，相传殷周之际匡氏兄弟七人在此结庐隐居故称匡庐，一北一南两座名山相对（课文照「玉屋」读，讲的就是王屋山）。第三层写景：「月明山寺远，风细水亭虚」，月明对风细（柳永词「月明风细」）、山寺对水亭（杜荀鹤诗「水亭山寺二年吟」）、远对虚——月色明净，山寺显得缥缈遥远；微风细细，水边亭子显得空旷清凉。落点：上一课认名物，这一课先记人、再记山、最后写意，对仗从认物走到了写景。韵脚如、庐、虚，同押六鱼。',
