        description: '《笠翁对韵》六鱼其二开篇。原文：「吾对汝，尔对余。选授对升除。书籍对药柜，耒耜对耰锄。」这一段从人称代词开讲：吾、余都是「我」，汝、尔都是「你」——我对你、你对我，第一人称对第二人称，是人称代词的入门一对，吾见《论语》「吾日三省吾身」，尔见《卖油翁》「尔安敢轻吾射」。选授是选拔授官，升除是升迁授职，「除」是拜官授职的意思，《陈情表》「除臣洗马」的「除」正是此义，两个词都是官场上的事，官职对官职。书籍对药柜（一本作「书箱」，书箱与药柜都是居家的柜匣），耒耜对耰锄：耒耜念 lěi sì，耒是柄、耜是头，是翻土的农具，神农氏「斫木为耜，揉木为耒」；耰念 yōu，是播种后用来覆土碎土的农具，《论语·微子》「耰而不辍」说的就是它，锄是锄头——四样器物，两两相对。落点：人称对人称、官职对官职、器物对器物——什么样的词找什么样的伴，同门类相对才算工对。韵脚余、除、锄，同押六鱼。',
