        description: '《笠翁对韵》六鱼其二第二段。原文：「参虽鲁，回不愚。阀阅对阎闾。诸侯千乘国，命妇七香车。」开头是两位孔子弟子的评语：参是曾参（曾子），孔子说他「参也鲁」，鲁是迟钝；回是颜回，《论语·为政》「吾与回言终日，不违，如愚。退而省其私，亦足以发，回也不愚」——看起来像愚，其实不愚，人对人、评语对评语。阀阅指世代有功勋的官宦人家：古代仕宦人家大门左边柱子记功叫「阀」、右边柱子记经历叫「阅」，合称阀阅；阎闾是里巷的门，阎是巷门、闾是里门，代指平民住的地方——门第对里巷，贵对贱。诸侯千乘国：乘念 shèng，一辆兵车叫一乘，千乘之国是有兵车千辆的大诸侯国，《论语·学而》「千乘之国，敬事而信」（本站第 8 课讲过）；命妇是受有封号的妇人，七香车是用多种香木香料制作的车子，是富贵人家的坐驾。落点：弟子对弟子、门第对里巷、大国对小车——同类才相对，样样配得上身份。韵脚闾、车（jū），同押六鱼。',
