        description: '《笠翁对韵》八齐其一第三段，其一收官。原文：「狡兔能穿三穴隐，鹪鹩权借一枝栖。甪里先生，策杖垂绅扶少主；於陵仲子，辟纑织履赖贤妻。」狡兔三穴出《战国策》：冯谖替孟尝君谋划，先烧债契买人心，再请封地、立宗庙，说狡兔有三窟才免一死；三不是实数，是说退路不止一条。鹪鹩读 jiāo liáo，一种小鸟，窝做得精巧又叫巧妇鸟，《庄子·逍遥游》「鹪鹩巢于深林，不过一枝；偃鼠饮河，不过满腹」，说的是所需有限；权是暂且、姑且，不是权力。甪里先生读 lù lǐ，姓周名术，商山四皓之一，秦末躲进商山、汉初不肯做官；汉高祖要废太子刘盈改立戚夫人之子，吕后急，张良出计请四皓陪侍太子，刘邦见四人随行，说「羽翼已成」，遂不废——策杖是拄拐，垂绅是大带下垂，都是老臣的样子。於陵仲子即陈仲子，居於陵（读 wū líng），哥哥做齐国大官他嫌不义，躲进山里守清贫；辟读 pì、纑读 lú，辟纑是把麻搓成线，织履是编草鞋，妻子搓线、丈夫编鞋，靠手艺换粮，故说「赖贤妻」。落点：兔子留三条退路是防身，鹪鹩占一根枝是知足；甪里先生出山扶储君，於陵仲子进山靠贤妻——一出一处，都是不肯将就的人，对起来却一样工整。韵脚栖、妻，同押八齐。',
        status: 'ready',
        duration: '约 15 分钟',
        subject: 'liwengduiyun',
