        path: 'lessons/652-jiang-xian-lao/index.html',
        grade: '小学低中年级',
        description: '《笠翁对韵》八齐其二第二段。原文：「绛县老，伯州犁。测蠡对燃犀。榆槐堪作荫，桃李自成蹊。」绛县老出《左传》：晋国绛县有位老人，无子，被征筑城，人家问他年岁，他只记得生日是甲子日，到如今过了四百四十五个甲子，师旷一算，断为七十三岁，后世以「绛老」称高寿。伯州犁是晋国大夫伯宗之子，伯宗被杀后逃楚任太宰；楚攻郑，穿封戌捉了郑将皇颉，公子围来抢功，他抬手指上说「这是王子围」、放下手指说「这是县尹穿封戌」，问俘虏谁捉的你，俘虏会意说是王子——「上下其手」即出此，喻玩弄手法、串通作弊。蠡读 lí，是葫芦做的瓢，《汉书》「以蠡测海」拿瓢量海，喻见识浅；燃犀是晋朝温峤过牛渚矶，燃犀角照水，水族现形，喻洞察幽微——一个照不见底、一个照见底，正相反成对。榆槐长得快、荫凉大，古人种在道旁村口歇脚，槐更列周代三公之位，故带官气；荫读 yìn。蹊读 xī，人走出来的小路；「桃李不言，下自成蹊」出《史记·李将军列传》，司马迁用它赞李广嘴笨而天下服，后「桃李」亦指学生。落点：绛县老不肯说、伯州犁绕着说，前两个讲嘴、后两个讲德；话说得少，人来得近。韵脚犁、犀、蹊，同押八齐。',
        status: 'ready',
