        grade: '小学低中年级',
        description: '《笠翁对韵》八齐其三第二段，八齐到此讲完。原文：「修月斧，上天梯。螮蝀对虹霓。行乐游春圃，工谀病夏畦。」修月斧出唐段成式《酉阳杂俎》：有人在嵩山遇白衣人，说月亮是七宝合成的，凸处挡光便成月影，日久会坏，要八万二千户各持斧凿上天修补，他是其中之一；后人以「修月手」「修月之斧」夸人本事极大，苏轼「从来修月手，合在广寒宫」即此。上天梯字面是登天的梯子，李白写蜀道「天梯石栈相钩连」，指悬崖上像梯子一样接上去的栈道；话里比喻飞黄腾达的门路，唐卢藏用隐居终南山等征召，司马承祯讥为「做官的捷径」，遂有「终南捷径」之说。螮蝀读 dì dōng，是虹的别名，二字皆虫旁，古人视虹为龙蛇一类，《诗经》「螮蝀在东，莫之敢指」；虹霓是同一道彩虹的两圈，古分雌雄，内圈色鲜者为虹属雄，外圈色淡者为霓属雌，亦称副虹，实为阳光在水珠中两次折射。行乐游春圃，圃是种菜种花的园子，春圃即春天之园，花开菜嫩风暖，人在其中游赏自得。工谀病夏畦出《孟子·滕文公下》「胁肩谄笑，病于夏畦」：工谀是擅长说奉承话，病是苦，畦是菜地一垄一垄的地，耸肩堆笑讨好人之苦，甚于盛夏在菜畦浇水；与上句一乐一苦，恰成对照。落点：本事要大，腰杆要直。韵脚梯、霓、畦，同押八齐。',
