        path: 'lessons/656-li-guang-bu-feng/index.html',
        grade: '小学低中年级',
        description: '《笠翁对韵》八齐其三第三段，八齐到此全部讲完。原文：「李广不封空射虎，魏明得立为存麑。按辔徐行，细柳功成劳王敬；闻声稍卧，临泾名震止儿啼。」李广守右北平出猎，见草中石以为虎而射之，箭镞没入石中，再射则不能入；与匈奴七十余战功多而终不得封侯，汉制封侯须按斩首俘获计功，其战多为遭遇守城，又屡有全军覆没，功过相抵，故王勃有「冯唐易老，李广难封」之叹，「空」字最重，是白费之意。魏明即魏明帝曹叡，曹丕猎时射杀母鹿，命其射小鹿，曹叡不肯，曰「陛下已杀其母，臣不忍复杀其子」，因涕泣，曹丕放弓，深奇之，树立之意遂定；麑读 ní，指幼鹿。细柳为周亚夫军营，在今陕西咸阳西南，汉文帝劳军，先驱至营门不得入，都尉答「军中闻将军令，不闻天子之诏」，文帝亲至亦不得入，遣使持节下诏乃开壁门；营门士吏又言「将军约，军中不得驱驰」，天子遂按辔徐行，成礼而去，叹「此真将军矣，乡者霸上、棘门如儿戏耳」；按辔即拉住缰绳，辔读 pèi。临泾在今甘肃镇原，为唐防吐蕃前线，郝玼读 hǎo cī，贞元中为临泾镇将，守边三十年，每战不持糗粮取之于敌，吐蕃畏之如神，不敢过临泾，蕃中儿啼者呼其名以怖之，赞普下令生得郝玼者赏以等身金；闻声稍卧即闻其名而伏下不敢动。落点：命不由人，威自己挣。韵脚麑、啼，同押八齐。',
