        subtitle: '《笠翁对韵》九佳其一第二段：登楚岫，渡秦淮',
        path: 'lessons/658-deng-chu-xiu/index.html',
        grade: '小学低中年级',
        description: '《笠翁对韵》九佳其一第二段。原文：「登楚岫，渡秦淮。子犯对夫差。石鼎龙头缩，银筝雁翅排。」岫读 xiù，本指山洞，也泛指山峰，陶渊明「云无心以出岫」；楚岫即楚地的山，巫山十二峰在楚。秦淮河在南京，本名淮水，相传秦始皇东巡凿方山引淮水北入长江，河改道故称秦淮；六朝建都于此，杜牧《泊秦淮》「商女不知亡国恨，隔江犹唱后庭花」。子犯姓狐名偃，是晋文公重耳的舅父，随其流亡十九年，助其归国即位，城濮一战退避三舍而败楚，成就霸业。夫差是吴王阖闾之子，阖闾伐越伤重而死，夫差使人日日提醒报仇，三年后败越于夫椒；后听信谗言逼死伍子胥，北上黄池争霸，被勾践乘虚灭国，自刭而亡。石鼎为石制之鼎，三足两耳，本以煮肉，后为礼器，鼎盖铸龙首而收敛不张，故曰龙头缩，全在静处。银筝为镶银之筝，唐宋十三弦，弦下小柱名雁柱，斜列如雁阵成行，故曰雁翅排，温庭筠「雁柱十三弦，一一春莺语」，全在动处。四句由山水行旅写到人物兴亡，再落到器物，一收一放、一静一动。落点：收得住，才立得住。韵脚淮、差、排，同押九佳。',
