        description: '《笠翁对韵》九佳其一第三段，其一至此收官。原文：「百年诗礼延余庆，万里风云入壮怀。能辨名伦，死矣野哉悲季路；不由径窦，生乎愚也有高柴。」诗礼指《诗经》与《礼记》，代指读书人家的家教；孔子在院中叫住儿子鲤问「学诗乎」「学礼乎」，谓「不学诗，无以言；不学礼，无以立」，即过庭之训。余庆出自《易·坤·文言》「积善之家，必有余庆」，谓先人积善所留之福泽；延为留传，百年谓三代四代相继。万里谓天下，风云谓时局变幻，壮怀谓豪壮胸怀，岳飞《满江红》「抬望眼，仰天长啸，壮怀激烈」。季路即子路，姓仲名由，孔门中最刚直者；子路问为政奚先，孔子答「必也正名乎」，子路讥其迂，孔子斥「野哉由也」。前四八〇年卫国孔悝作乱，子路言「食其食者不避其难」，入城战死，缨断而结缨，曰「君子死，冠不免」。高柴字子羔，孔子评为「柴也愚」，愚谓朴厚不敏；卫乱出走，郭门已闭，守门者指缺口与墙洞令其出入，子羔答「君子不逾」「君子不隧」，终由守门人所指之室得免；其人即昔年被子羔判罪刖足者，因执法公允而救之。径为小路，窦读 dòu，为墙洞。四句由家风与志向写到孔门二弟子，一刚一愚、一死一生，所守皆为规矩。落点：老实人不吃亏，只是慢一点。韵脚怀、柴，同押九佳。',
