        description: '《笠翁对韵》九佳其二第二段。原文：「陈俎豆，戏堆埋。皎皎对皑皑。贤相聚东阁，良朋集小斋。」陈俎豆出《史记·孔子世家》「孔子为儿嬉戏，常陈俎豆，设礼容」；俎读 zǔ，为祭祀时盛牲肉的长方木盘，豆为盛食物之高脚器皿，两样皆礼器，合称代指礼仪，陈为陈列。戏堆埋出《列女传·母仪传》，孟子幼时家近墓地，「嬉游为墓间之事，踊跃筑埋」，堆埋即埋人垒坟头，孟母因此三迁至学宫之旁。皎皎读 jiǎo，洁白明亮，多写月色，《诗经》「皎皎白驹」；皑皑读 ái，雪白，多写霜雪，《白头吟》「皑如山上雪」；一写月之亮白，一写雪之厚白，同中见异。贤相聚东阁用汉公孙弘事，弘少时家贫牧豕海上，年四十余始学《春秋》，后官至丞相封平津侯，「起客馆，开东阁以延贤人」，东阁遂为招贤之代称。良朋集小斋用唐柳公绰事，其家中门东有小斋，非朝谒之日每平旦辄至小斋，诸子束带晨省；斋读 zhāi，为书房。四句由两个幼童写到两类白，再写到两处人聚，一公一私、一大一小。落点：小时候玩什么，长大就做什么。韵脚埋、皑、斋，同押九佳。',
