        description: '《笠翁对韵》九佳其三第二段。原文：「寒翠袖，贵荆钗。慷慨对诙谐。竹径风声籁，花溪月影筛。」寒翠袖出杜甫《佳人》「天寒翠袖薄，日暮倚修竹」，翠袖为青绿衣袖，代指女子，寒状其清苦而不失态。荆钗为荆木所制发钗，贫家妇女所戴；通行本作「贵荆钗」而非「贵金钗」，谓以木钗为贵、不慕金玉，若作金钗则与「贵」字意重；典出梁鸿妻孟光荆钗布裙、举案齐眉。慷慨谓意气激昂，亦指乐善好施，如荆轲易水送别、高渐离击筑而歌；诙谐谓谈吐风趣，如东方朔在汉武帝前诙笑切谏；一庄一谐，一硬一软。籁读 lài，本指孔窍所发之声，《庄子·齐物论》分天籁、地籁、人籁，风穿竹林不待人吹而自响，是为天籁。筛读 shāi，本为筛子，此处作动词，谓月光透过花枝细碎洒落，如经筛过，一地细影。竹对花、径对溪、风声对月影，一听一看，对仗极工。四句先写人后写景。落点：身上清苦，眼里有景。韵脚钗、谐、筛，同押九佳。',
