        path: 'lessons/684-you-dui-xi/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「忧对喜，戚对欣。五典对三坟。佛经对仙语，夏耨对春耘。」此段见《笠翁对韵》上卷十二文其一开篇，接683课十一真其三之后，自「真」韵转入「文」韵。忧、喜、戚、欣四字皆言心境：忧为愁，喜为乐，戚为悲，欣为悦，两两同类而正反相对。戚本义为斧，借为亲属之称，又引申为悲戚，此处作悲伤解。五典、三坟为上古书籍之名，出《左传·昭公十二年》「是能读三坟、五典、八索、九丘」。孔安国《尚书序》谓伏羲、神农、黄帝之书为三坟，言大道；少昊、颛顼、高辛、唐、虞之书为五典，言常道。坟非坟墓，乃大之意。此类古书今多不存，仅余其名。佛经谓佛教典籍，自印度译入；仙语谓道家之言，如《老子》《庄子》，一外来一本土，同类相对。耨读nòu，除草；耘读yún，除草培土。夏耨对春耘，农事相同而季节相对，换字所以避复。全段四组，皆就同类中取相对者：心情对心情，典籍对典籍，教门对教门，农活对农活。落点：耕读传家，日子就稳。',
