        description: '对韵段，原文：「烹早韭，剪春芹。暮雨对朝云。竹间斜白接，花下醉红裙。」此段见《笠翁对韵》上卷十二文其一收尾，接684课「夏耨对春耘」之后。烹早韭、剪春芹，两样都是早春的时鲜菜蔬：烹是下锅煮，剪是下地割。《南史》有「春初早韭，秋末晚菘」之说，杜甫《赠卫八处士》又有「夜雨剪春韭，新炊间黄粱」，都是这一句的来处。暮雨对朝云，出宋玉《高唐赋》巫山神女语「旦为朝云，暮为行雨，朝朝暮暮，阳台之下」，后世「朝云暮雨」遂成典故。暮对朝是时间相对，雨对云是天象相对。竹间斜白接，白接即白接䍦，白色头巾，䍦读lí。《世说新语·任诞》记时人歌「山公时一醉，径造高阳池。日莫倒载归，酩酊无所知。复能乘骏马，倒著白接䍦」，山简镇襄阳事；李白《襄阳歌》「倒著接䍦花下迷」即用此。花下醉红裙，红裙指穿红裙的女子，与上句白头巾一物一人相对；旧注亦有指红花之说。竹间对花下是地方相对，斜对醉是姿态相对，白对红是颜色相对。全段四组，写的都是家常物、眼前景。落点：身边的物，也能入诗。',
