        description: '对韵段，原文：「掌握灵符五岳篆，腰悬宝剑七星纹。金锁未开，上相趋听宫漏永；珠帘半卷，群僚仰对御炉薰。」此段见《笠翁对韵》上卷十二文其一，接685课「花下醉红裙」之后。前两句写仙家法器：掌握即攥在手里；灵符是道士所画之符，五岳指东岳泰山、西岳华山、南岳衡山、北岳恒山、中岳嵩山，古人以为天下大山之代表，各有神主；篆指符上笔画弯曲如篆书，别本作「箓」，读lù，为道教记神名之秘文。腰悬即佩在腰间；七星为北斗（天枢、天璇、天玑、天权、玉衡、开阳、摇光），道教以北斗为司命之神，剑刻七星纹者即法剑。掌握对腰悬是部位相对，灵符对宝剑是法器相对，五岳对七星是地对天。后两句写朝廷朝仪：金锁是宫门之锁，未开见天时之早；上相即宰相，趋为小步快走示敬之礼；宫漏是宫中铜壶滴漏，永是长，写宰相门外待漏之勤。珠帘为珠缀之帘，半卷留半幅；群僚即百官，仰对是抬头向着；御炉为御用香炉，薰是香气熏染。金锁对珠帘是门外对殿上，未开对半卷是状态相对，上相对群僚是一人对百官，趋对仰是俯身对抬头，听对看是耳对目。全段两组，一组仙家一组朝堂，皆写威仪。落点：仙有仙的威，朝有朝的仪。',
