        path: 'lessons/688-yan-xu-bi/index.html',
        grade: '小学低中年级',
        description: '对韵段，原文：「燕许笔，韩柳文。旧话对新闻。赫赫周南仲，翾翾晋右军。」此段见《笠翁对韵》上卷十二文其二中段，接687课「带草对香芸」之后。燕许笔：唐代燕国公张说、许国公苏颋，二人以文章名世，时称「燕许大手笔」，笔指文章、文笔。韩柳文：唐代韩愈、柳宗元，倡导古文运动，位列唐宋八大家，文章冠绝一代。两组都是文章家，两人对两人，笔对文，故能成对。旧话对新闻：旧是老话，新闻古义指新近听来的事、新鲜见闻，不是今天的报纸。旧对新是反义相对，话对闻都跟言语听闻有关，是同类相对。赫赫周南仲：南仲是周宣王时大将，曾率兵打退北方玁狁（xiǎn yǔn），《诗经·小雅·出车》有「赫赫南仲，玁狁于襄」，赫赫是威武显赫的样子。翾翾晋右军：晋右军指东晋书法家王羲之，官至右军将军，人称王右军，作《兰亭序》，被尊为书圣；翾读 xuān，《说文》「翾，小飞也」，翾翾是轻快飞舞的样子，这里形容举止飘逸洒脱。通行本此句多作「翩翩」或「翮翮」，意思相近，本课按原文「翾翾」讲。叠词相对，一武一雅，各写一样真本事。落点：各有各的本事，各留各的名。',
